<script>(()=>{const f=document.getElementById("contact-form-fields"),msg=document.getElementById("message"),count=document.getElementById("message-count");msg.addEventListener("input",()=>count.textContent=msg.value.length+" / 2000");const c={name:{e:document.getElementById("name"),t:v=>v.trim().length>=2,m:"Please enter your name (at least 2 characters)."},email:{e:document.getElementById("email"),t:v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),m:"Please enter a valid email address."},interest:{e:document.getElementById("interest"),t:v=>v!=="",m:"Please choose a product or area."},message:{e:msg,t:v=>v.trim().length>=10,m:"Please add a little more detail (at least 10 characters)."}};function check(k){const x=c[k],p=document.getElementById(k+"-error"),ok=x.t(x.e.value);p.textContent=ok?"":x.m;p.classList.toggle("hidden",ok);x.e.setAttribute("aria-invalid",String(!ok));return ok}Object.keys(c).forEach(k=>{c[k].e.addEventListener("blur",()=>check(k));c[k].e.addEventListener("input",()=>{if(c[k].e.getAttribute("aria-invalid")==="true")check(k)})});f.addEventListener("submit",e=>{const bad=Object.keys(c).map(check).some(ok=>!ok);if(!f.querySelector("[name=consent]").checked){f.querySelector("[name=consent]").focus();e.preventDefault()}if(bad){e.preventDefault();f.querySelector("[aria-invalid=true]")?.focus()}})})();</script>
